function switchView(v){if(!titles[v])return;$('missionControls').hidden=v==='feedback'||v==='compare';document.querySelector('.notice').hidden=v==='feedback';$('export').hidden=v==='feedback';requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'instant'}));$('spaceIntro').hidden=v!=='overview';document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===v));document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===v));$('viewTitle').textContent=titles[v][0];$('viewSubtitle').textContent=titles[v][1];if(v==='terrain')drawSlope();if(v==='link')drawProfile();location.hash=v;}
