function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500);}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function lastPlanningIndex(){return Math.max(0,(records.length||17520)-169);}
function dateIndex(){const d=new Date($('date').value+'Z');return Math.max(0,Math.min(lastPlanningIndex(),Math.round((d-Date.UTC(2025,0,1))/3600000)));}
function direction(s,p,distance=1e15,height=0){const la=s.lat*rad,lo=s.lon*rad,tl=p.lat*rad,dl=(p.lon-s.lon)*rad;let east=distance*Math.cos(tl)*Math.sin(dl),north=distance*(Math.cos(la)*Math.sin(tl)-Math.sin(la)*Math.cos(tl)*Math.cos(dl)),up=distance*(Math.sin(la)*Math.sin(tl)+Math.cos(la)*Math.cos(tl)*Math.cos(dl))-(R+height);return{el:Math.atan2(up,Math.hypot(east,north))*deg,az:(Math.atan2(east,north)*deg+360)%360};}
function horizon(s,az,height){return Math.max(-Math.acos(R/(R+height))*deg,s.mask+.9*Math.sin((az+30)*rad)+.65*Math.sin((az*3+50)*rad)-Math.atan2(height,700)*deg);}
