function stats(arr,key){let run=0,max=0,count=0;for(const a of arr){if(a[key]){count++;run=0;}else{run++;max=Math.max(max,run);}}return{pct:Math.round(count/arr.length*100),out:max};}
function update(){const i=+$('site').value,s=sites[i],h=+$('height').value;$('heightLabel').textContent=h+' m';$('coords').textContent=Math.abs(s.lat).toFixed(2)+'° '+(s.lat<0?'S':'N')+' / '+Math.abs(s.lon).toFixed(2)+'° '+(s.lon<0?'O':'E');if(!records.length || !$('date').value || !$('date').checkValidity())return;const idx=dateIndex();current=evaluate(s,records[idx],h);series=records.slice(idx,idx+168).map(r=>evaluate(s,r,h));const es=stats(series,'ev');$('earthEl').textContent=current.earth.el.toFixed(2)+'°';$('sunEl').textContent=current.sun.el.toFixed(2)+'°';$('earthState').textContent=current.ev?'Sobre horizonte demo':'Bajo horizonte demo';$('earthState').style.color=current.ev?'#55dba4':'#fbbf24';$('sunState').textContent=current.sv?'Sobre horizonte demo':'Bajo horizonte demo';$('visibility').textContent=es.pct+' %';$('outage').textContent=es.out+' h';$('footerTime').textContent=records[idx].time+' · datos SVS 2025–2026';$('insight').textContent=current.ev?'La dirección hacia la Tierra supera el horizonte LOLA muestreado. Falta evaluar estación terrestre y balance de enlace.':'El horizonte de ejemplo bloquea la dirección hacia la Tierra. Probá otra altura o sitio.';drawHorizon(s,h,current);drawTimeline(idx);drawCompare();updateSiteSummary(idx);updateEnergy();drawGlobe();}
function horizonMarkup(s,h,c){const W=600,H=280,x=a=>42+a/360*535,y=e=>220-(e+8)/24*190;let html='';for(let e=-8;e<=16;e+=4)html+=`<line class="grid" x1="42" y1="${y(e)}" x2="577" y2="${y(e)}"/><text x="4" y="${y(e)+4}">${e}°</text>`;let pts=[];for(let a=0;a<=360;a+=2)pts.push([x(a),y(horizon(s,a,h))]);html+=`<path d="M42 233 L${pts.map(p=>p.join(' ')).join(' L')} L577 233Z" fill="#2c405e"/><line x1="42" x2="577" y1="${y(0)}" y2="${y(0)}" stroke="#66809d" stroke-dasharray="4 5"/>`;for(const a of [0,90,180,270,360])html+=`<text x="${x(a)-8}" y="259">${a}°</text>`;for(const [p,col,name] of [[c.earth,'#22d3ee','Tierra'],[c.sun,'#fbbf24','Sol']]){const yy=y(Math.max(-8,Math.min(16,p.el)));html+=`<line x1="${x(p.az)}" y1="30" x2="${x(p.az)}" y2="233" stroke="${col}" opacity=".2"/><circle cx="${x(p.az)}" cy="${yy}" r="6" fill="${col}"/><text class="label" x="${Math.max(43,Math.min(490,x(p.az)+10))}" y="${Math.max(19,yy-12)}">${name} ${p.el.toFixed(1)}°</text>`;}html+='<text x="450" y="279">Azimut desde el norte</text>';return html;}
