function drawTimeline(idx){const rows=[['Tierra visible','ev','#22d3ee'],['Sol visible','sv','#fbbf24'],['Ambos visibles','both','#55dba4']];$('timeline').innerHTML=rows.map(([label,key,col])=>`<div class="timeline-row"><span>${label}</span><div class="track">${series.map((a,n)=>`<i title="${records[idx+n].time}: ${(key==='both'?a.ev&&a.sv:a[key])?'visible':'oculto'}" style="background:${(key==='both'?a.ev&&a.sv:a[key])?col:'#1e2c42'}"></i>`).join('')}</div></div>`).join('')+`<div class="timeline-dates">${[0,48,96,167].map(n=>`<span>${new Date(Date.UTC(2025,0,1,idx+n)).toISOString().slice(5,16).replace('T',' ')}</span>`).join('')}</div>`;}
function terrain(x,y){return 60*Math.exp(-((x-420)**2+(y-500)**2)/20000)-95*Math.exp(-((x-620)**2+(y-390)**2)/32000)+8*Math.sin(x/60)*Math.cos(y/80)+.03*x;}
