function selectLanding(id,focus=true){const s=historicalSites.find(a=>a.id===id);if(!s)return;selectedLanding=id;$('landingSelect').value=id;if(focus){rotation=s.lon*rad;latitude=s.lat*rad;drawGlobe();}else renderLandingMarkers();$('landingDetail').innerHTML=`<div><b style="color:${landingColors[s.group]}">${s.name}</b><span>${s.object}</span></div><div><small>LATITUD / LONGITUD</small><strong>${Math.abs(s.lat).toFixed(4)}° ${s.lat<0?'S':'N'} · ${Math.abs(s.lon).toFixed(4)}° ${s.lon<0?'O':'E'}</strong></div><div><small>ELEVACIÓN PUBLICADA</small><strong>${s.elevation_m.toLocaleString('es-AR')} m</strong></div><a href="https://www.lroc.asu.edu/data/support/downloads/2016_LROC_Coordinates_of_Human_Features.pdf" target="_blank" rel="noopener">Fuente LROC ↗</a>`;}
function updateLandingFilter(){const list=filteredLandings();$('landingSelect').replaceChildren(...list.map(s=>{const o=document.createElement('option');o.value=s.id;o.textContent=s.name;return o;}));selectLanding(list.some(s=>s.id===selectedLanding)?selectedLanding:list[0].id,false);}
$('landingFilter').onchange=updateLandingFilter;$('landingSelect').onchange=e=>selectLanding(e.target.value);$('nearside').onclick=()=>{rotation=0;latitude=.08;drawGlobe();};
window.addEventListener('load',()=>{if(!location.hash||titles[location.hash.slice(1)])window.scrollTo({top:0,behavior:'instant'});});
fetch('assets/landing-sites.json').then(r=>{if(!r.ok)throw Error('No se pudo cargar el catálogo histórico');return r.json();}).then(data=>{historicalSites=data.sites;updateLandingFilter();drawGlobe();}).catch(e=>{$('landingCount').textContent=e.message;});
// The NASA Sun model is a visual layer; illumination calculations stay independent.
const sunModel=$('sunModel'),sunDialog=$('sunDialog');
sunModel.addEventListener('load',()=>{$('sunStatus').textContent='3D listo · arrastrá para rotar';});
sunModel.addEventListener('error',()=>{$('sunStatus').innerHTML='No se pudo cargar el 3D. <a href="https://solarsystem.nasa.gov/gltf_embed/2352/" target="_blank" rel="noopener">Abrir NASA ↗</a>';});
$('expandSun').onclick=()=>{if(!$('sunExpandedMount').firstElementChild){const model=document.createElement('model-viewer');for(const [k,v]of Object.entries({src:'assets/sun-nasa.glb',alt:'Modelo 3D ampliado del Sol de NASA','camera-controls':'','auto-rotate':'','interaction-prompt':'none','shadow-intensity':'0',exposure:'1','touch-action':'pan-y'}))model.setAttribute(k,v);$('sunExpandedMount').append(model);}sunDialog.showModal();};
$('closeSun').onclick=()=>sunDialog.close();sunDialog.addEventListener('click',e=>{if(e.target===sunDialog){const box=sunDialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)sunDialog.close();}});
// A common diameter scale is separate from independently framed 3D models.
const earthModel=$('earthModel');earthModel.addEventListener('load',()=>{$('earthStatus').textContent='3D listo · rotación y zoom';});earthModel.addEventListener('error',()=>{$('earthStatus').textContent='No se pudo cargar el modelo 3D';});
function openPlanet(kind){const earth=kind==='earth',name=earth?'Tierra':'Sol';$('sunDialogTitle').textContent=name+' · modelo 3D de NASA';const mount=$('sunExpandedMount');if(mount.dataset.body!==kind){mount.replaceChildren();const model=document.createElement('model-viewer');for(const[k,v]of Object.entries({src:'assets/'+kind+'-nasa.glb',alt:'Modelo 3D ampliado de '+name+' de NASA','camera-controls':'','auto-rotate':'','interaction-prompt':'none','shadow-intensity':'0',exposure:'1','touch-action':'pan-y'}))model.setAttribute(k,v);mount.append(model);mount.dataset.body=kind;}sunDialog.querySelector('.sun-dialog-foot a').href='https://solarsystem.nasa.gov/gltf_embed/'+(earth?'2393':'2352')+'/';sunDialog.showModal();}
$('expandSun').onclick=()=>openPlanet('sun');$('expandEarth').onclick=()=>openPlanet('earth');
const feedbackAreas=[{id:'overview',name:'Centro de misión',profile:'Visualización, astronomía y divulgación',question:'¿Se entiende cómo la posición del Sol y la Tierra sobre el horizonte afecta la misión?'},{id:'terrain',name:'Relieve y pendientes',profile:'Geociencias, movilidad y análisis de datos',question:'¿El mapa y la fórmula ayudan a entender el terreno y sus limitaciones?'},{id:'link',name:'Radioenlace',profile:'Ingeniería en telecomunicaciones',question:'¿Son claros el perfil, las alturas, Fresnel y la diferencia entre visibilidad y margen ideal?'},{id:'compare',name:'Comparar sitios y fechas',profile:'Planificación de misión y decisiones',question:'¿Las métricas permiten comparar sitios? ¿Qué criterio falta?'},{id:'energy',name:'Energía y supervivencia',profile:'Energía, electrónica y térmica',question:'¿Se entiende autonomía eléctrica frente a supervivencia térmica?'},{id:'sources',name:'Datos y metodología',profile:'Investigación, software y validación',question:'¿Se distingue qué es real, aproximado y demostrativo, y cómo validarlo?'}];
$('feedbackAreas').innerHTML=feedbackAreas.map(a=>`<article><div class="eyebrow">${a.profile}</div><h3>${a.name}</h3><p>${a.question}</p><div class="buttonrow"><button type="button" data-explore-area="${a.id}">Explorar ↗</button><button type="button" data-review-area="${a.id}">Evaluar esta área</button></div></article>`).join('');$('feedbackArea').replaceChildren(...feedbackAreas.map(a=>{const o=document.createElement('option');o.value=a.id;o.textContent=a.name;return o;}));
document.querySelectorAll('[data-explore-area]').forEach(b=>b.onclick=()=>switchView(b.dataset.exploreArea));document.querySelectorAll('[data-review-area]').forEach(b=>b.onclick=()=>{$('feedbackArea').value=b.dataset.reviewArea;$('feedbackComment').focus();saveFeedbackDraft();});
const feedbackKeys=['feedbackName','feedbackArea','feedbackRating','feedbackComment','feedbackContribution'];function saveFeedbackDraft(){try{localStorage.setItem('lunar-zcs-feedback-draft',JSON.stringify(Object.fromEntries(feedbackKeys.map(k=>[k,$(k).value]))));$('feedbackStatus').textContent='Borrador guardado solo en este navegador.';}catch{$('feedbackStatus').textContent='No se pudo guardar el borrador. Podés copiarlo o descargarlo.';}}
try{const draft=JSON.parse(localStorage.getItem('lunar-zcs-feedback-draft')||'null');if(draft&&typeof draft==='object')for(const k of feedbackKeys)if(typeof draft[k]==='string')$(k).value=draft[k].slice(0,k==='feedbackComment'?4000:k==='feedbackContribution'?2000:80);}catch{}feedbackKeys.forEach(k=>$(k).addEventListener('input',saveFeedbackDraft));
function feedbackText(){const area=feedbackAreas.find(a=>a.id===$('feedbackArea').value);return '# Feedback · Lunar ZCS\n\nFecha: '+new Date().toISOString()+'\nIntegrante: '+($('feedbackName').value.trim()||'Sin nombre')+'\nÁrea: '+(area?.name||'Sin elegir')+'\nClaridad: '+($('feedbackRating').value?$('feedbackRating').value+'/5':'Sin puntuar')+'\n\n## Qué entendí y qué mejoraría\n'+$('feedbackComment').value.trim()+'\n\n## Aporte desde mi especialidad\n'+($('feedbackContribution').value.trim()||'Sin indicar')+'\n\nInterfaz: '+location.origin+'/#'+$('feedbackArea').value+'\n';}
$('feedbackForm').onsubmit=e=>{e.preventDefault();if(!$('feedbackForm').reportValidity())return;download('feedback-lunar-zcs-'+$('feedbackArea').value+'.md',feedbackText(),'text/markdown;charset=utf-8');$('feedbackStatus').textContent='Feedback descargado. Envialo al equipo para que lo puedan reunir.';};$('copyFeedback').onclick=async()=>{if(!$('feedbackForm').reportValidity())return;try{await navigator.clipboard.writeText(feedbackText());$('feedbackStatus').textContent='Copiado. Pegalo en el chat del equipo.';}catch{$('feedbackStatus').textContent='No se pudo copiar. Usá Descargar feedback.';}};
$('shareLink').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/#feedback');toast('Enlace para dar feedback copiado.');}catch{toast('Compartí la dirección de esta página con #feedback al final.');}};
$('clearFeedback').onclick=()=>{try{localStorage.removeItem('lunar-zcs-feedback-draft');}catch{}$('feedbackForm').reset();$('feedbackStatus').textContent='Borrador eliminado de este navegador.';};
function selectedIndex(input){const d=new Date(input.value+'Z');return Math.max(0,Math.min(lastPlanningIndex(),Math.round((d-Date.UTC(2025,0,1))/3600000)));}
function hoursLabel(idx){return new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC',hour12:false}).format(new Date(Date.UTC(2025,0,1,idx)))+' UTC';}
function visibleHours(arr,key){return arr.filter(a=>key==='both'?a.ev&&a.sv:a[key]).length;}
function firstVisibleWindow(arr,key){const start=arr.findIndex(a=>a[key]);if(start<0)return null;let end=start;while(end<arr.length&&arr[end][key])end++;return{start,end};}
function windowText(arr,key,idx){const w=firstVisibleWindow(arr,key);if(!w)return'Sin ventana visible en los próximos siete días del modelo.';const start=w.start===0?'Disponible ahora':'Próxima ventana desde '+hoursLabel(idx+w.start);return start+(w.end===arr.length?' · continúa al final del período.':' · hasta cerca de '+hoursLabel(idx+w.end)+'.')+' Resolución: 1 hora.';}
function updateSiteSummary(idx){const sh=visibleHours(series,'sv'),eh=visibleHours(series,'ev');$('sunAvailability').textContent=sh+' h de luz estimada / 168 h';$('earthAvailability').textContent=eh+' h de Tierra visible / 168 h';$('sunWindow').textContent=windowText(series,'sv',idx);$('earthWindow').textContent=windowText(series,'ev',idx);$('timePreviewLabel').textContent=hoursLabel(idx);}
function drawCompare(){if(!records.length)return;const height=number('compareHeight'),outputs=[];for(const side of ['A','B']){const input=$('compareDate'+side);if(!input.value||!input.checkValidity())return;const idx=selectedIndex(input),site=sites[+$('compareSite'+side).value],arr=records.slice(idx,idx+168).map(r=>evaluate(site,r,height)),earth=stats(arr,'ev'),sun=stats(arr,'sv'),solarHours=visibleHours(arr,'sv'),earthHours=visibleHours(arr,'ev'),both=visibleHours(arr,'both');outputs.push({side,idx,site,arr,earth,sun,solarHours,earthHours,both});$('compareHorizon'+side).innerHTML=horizonMarkup(site,height,arr[0]);$('scenarioStats'+side).innerHTML=`<div class="sun"><small>LUZ SOLAR</small><b>${solarHours} h</b><span>${sun.pct} % del período</span></div><div class="earth"><small>TIERRA VISIBLE</small><b>${earthHours} h</b><span>${earth.pct} % del período</span></div><div><small>COINCIDENCIA</small><b>${both} h</b><span>Sol + Tierra visibles</span></div>`;$('scenarioWindows'+side).innerHTML=`<p><span class="sun">☼ Sol ${arr[0].sun.el.toFixed(2)}°</span> · azimut ${arr[0].sun.az.toFixed(1)}°<br>${windowText(arr,'sv',idx)}</p><p><span class="earth">◎ Tierra ${arr[0].earth.el.toFixed(2)}°</span> · azimut ${arr[0].earth.az.toFixed(1)}°<br>${windowText(arr,'ev',idx)}</p>`;}$('compareRows').innerHTML=outputs.map(o=>`<tr><td><b>${o.side} · ${o.site.name}</b><br><span class="sub">${hoursLabel(o.idx)}</span></td><td>${o.solarHours} h / ${o.sun.pct} %</td><td>${o.earthHours} h / ${o.earth.pct} %</td><td>${o.both} h</td><td>${o.sun.out} h</td><td>${o.earth.out} h</td></tr>`).join('');const[a,b]=outputs;const solar=a.solarHours-b.solarHours,comm=a.earthHours-b.earthHours;const difference=(n,term)=>n===0?'Ambos escenarios tienen las mismas horas de '+term+'.':`El escenario ${n>0?'A':'B'} tiene ${Math.abs(n)} h más de ${term}.`;$('compareVerdict').textContent=difference(solar,'luz solar')+' '+difference(comm,'visibilidad terrestre')+' Elegí qué condición prioriza tu misión; el modelo de horizonte está limitado al radio y resolución indicados.';}
for(const id of ['compareSiteA','compareSiteB','compareDateA','compareDateB','compareHeight'])$(id).addEventListener('input',drawCompare);
$('heroCompare').onclick=()=>{for(const side of ['A','B'])$('compareDate'+side).value=$('date').value;$('compareSiteA').value=$('site').value;$('compareSiteB').value=String((+$('site').value+1)%sites.length);$('compareHeight').value=$('height').value;drawCompare();switchView('compare');};
let scrubAnchor=selectedIndex($('date')),playTimer=null;
function resetScrubber(){scrubAnchor=selectedIndex($('date'));$('timeScrubber').value=0;$('timeScrubber').max=Math.max(0,Math.min(167,lastPlanningIndex()-scrubAnchor));$('scrubStart').textContent=hoursLabel(scrubAnchor);$('scrubEnd').textContent=hoursLabel(scrubAnchor+(+$('timeScrubber').max));}
function previewTime(){const idx=scrubAnchor+(+$('timeScrubber').value);$('date').value=new Date(Date.UTC(2025,0,1,idx)).toISOString().slice(0,16);update();}
function stopPlayback(){if(playTimer)clearInterval(playTimer);playTimer=null;$('playTime').textContent='▶ Recorrer horas';$('playTime').setAttribute('aria-pressed','false');}
$('timeScrubber').oninput=()=>{stopPlayback();previewTime();};$('date').addEventListener('change',()=>{stopPlayback();resetScrubber();});$('playTime').onclick=()=>{if(playTimer)return stopPlayback();if(+$('timeScrubber').value>=+$('timeScrubber').max)$('timeScrubber').value=0;$('playTime').textContent='Ⅱ Pausar';$('playTime').setAttribute('aria-pressed','true');playTimer=setInterval(()=>{if(!$('overview').classList.contains('active')||+$('timeScrubber').value>=+$('timeScrubber').max)return stopPlayback();$('timeScrubber').value=+$('timeScrubber').value+1;previewTime();},900);};resetScrubber();
function comparisonSnapshot(){if(!$('compare').classList.contains('active')||!records.length)return null;return{horizon_source:'LOLA Site01; 20m radial, 2deg azimuth, bounded radius',observer_height_m:number('compareHeight'),sampling_hours:1,scenarios:['A','B'].map(side=>{const idx=selectedIndex($('compareDate'+side)),site=sites[+$('compareSite'+side).value],arr=records.slice(idx,idx+168).map(r=>evaluate(site,r,number('compareHeight')));return{side,site,utc:new Date(Date.UTC(2025,0,1,idx)).toISOString(),sun_visible_hours:visibleHours(arr,'sv'),earth_visible_hours:visibleHours(arr,'ev'),both_visible_hours:visibleHours(arr,'both'),longest_dark_hours:stats(arr,'sv').out,longest_earth_outage_hours:stats(arr,'ev').out};})};}
$('compareSameDate').onclick=()=>{$('compareDateB').value=$('compareDateA').value;if($('compareSiteB').value===$('compareSiteA').value)$('compareSiteB').value=String((+$('compareSiteA').value+1)%sites.length);drawCompare();};$('compareSameSite').onclick=()=>{$('compareSiteB').value=$('compareSiteA').value;const idx=Math.min(lastPlanningIndex(),selectedIndex($('compareDateA'))+168);$('compareDateB').value=new Date(Date.UTC(2025,0,1,idx)).toISOString().slice(0,16);drawCompare();};$('swapScenarios').onclick=()=>{for(const field of ['compareSite','compareDate']){const a=$(field+'A').value;$(field+'A').value=$(field+'B').value;$(field+'B').value=a;}drawCompare();};
